import java.util.*;

public class Main {
    static Map<Integer, Integer> idxMap = new HashMap<>();
    static int preIdx = 0;
    static int[] preorder;

    static TreeNode buildTree(int[] preorderArr, int[] inorder) {
        preorder = preorderArr;
        preIdx = 0;
        for (int i = 0; i < inorder.length; i++) idxMap.put(inorder[i], i);   // value to index, built ONCE
        return build(0, inorder.length - 1);
    }

    static TreeNode build(int inLeft, int inRight) {
        if (inLeft > inRight) return null;
        int rootVal = preorder[preIdx++];                            // consume the NEXT preorder value
        TreeNode node = new TreeNode(rootVal);
        int mid = idxMap.get(rootVal);                                 // O(1) lookup
        node.left = build(inLeft, mid - 1);                              // left range
        node.right = build(mid + 1, inRight);                             // right range
        return node;
    }
}

