unordered_map<int, int> idxMap;
int preIdx = 0;
vector<int> preorderArr;

TreeNode* build(int inLeft, int inRight) {
    if (inLeft > inRight) return nullptr;
    int rootVal = preorderArr[preIdx++];                            // consume the NEXT preorder value
    TreeNode* node = new TreeNode(rootVal);
    int mid = idxMap[rootVal];                                        // O(1) lookup
    node->left = build(inLeft, mid - 1);                                // left range
    node->right = build(mid + 1, inRight);                               // right range
    return node;
}

TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
    preorderArr = preorder;
    preIdx = 0;
    for (int i = 0; i < (int)inorder.size(); i++) idxMap[inorder[i]] = i;   // value to index, built ONCE
    return build(0, inorder.size() - 1);
}
